'use strict';
function pdfText(s){return String(s??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[–—−]/g,'-').replace(/[‘’]/g,"'").replace(/[“”]/g,'"').replace(/→/g,' -> ').replace(/↓/g,' to ').replace(/≥/g,'>=').replace(/≤/g,'<=').replace(/×/g,'x').replace(/₩/g,'KRW ').replace(/€/g,'EUR ').replace(/[^\x20-\x7E\n]/g,' ')}
async function buildResearchPdf(model){if(!model?.title||!Array.isArray(model.sections)||!model.sections.length)throw Error('A research report needs a title and content sections');const {PDFDocument,StandardFonts,rgb,PDFName,PDFString}=PDFLib,doc=await PDFDocument.create(),regular=await doc.embedFont(StandardFonts.Helvetica),bold=await doc.embedFont(StandardFonts.HelveticaBold),ink=rgb(.063,.13,.21),muted=rgb(.37,.43,.5),blue=rgb(.19,.36,.8),green=rgb(.03,.45,.33);doc.setTitle(model.title);doc.setAuthor('AI Money Map');doc.setSubject('Dated financial research and conditional analysis');const W=595.28,H=841.89,M=44,C=W-2*M;let page,y,topic='';
function newPage(){page=doc.addPage([W,H]);y=H-76;page.drawText('AI MONEY MAP',{x:M,y:H-36,font:bold,size:10,color:ink});page.drawText('RESEARCH SNAPSHOT  |  3 OCT 2026',{x:W-251,y:H-36,font:regular,size:8,color:muted});page.drawLine({start:{x:M,y:H-46},end:{x:W-M,y:H-46},color:rgb(.8,.85,.88),thickness:.6});if(topic){page.drawText(pdfText(topic).slice(0,100),{x:M,y:y+7,font:regular,size:8,color:muted});y-=11}}
function ensure(h){if(!page||y-h<54)newPage()}
function wrap(text,width,size,font=regular){const result=[];for(const para of pdfText(text).split('\n')){let line='';for(let word of para.split(/\s+/)){if(!word)continue;while(font.widthOfTextAtSize(word,size)>width){let n=1;while(n<word.length&&font.widthOfTextAtSize(word.slice(0,n+1),size)<width)n++;if(line){result.push(line);line=''}result.push(word.slice(0,n));word=word.slice(n)}const test=line?line+' '+word:word;if(font.widthOfTextAtSize(test,size)>width&&line){result.push(line);line=word}else line=test}result.push(line)}return result}
function para(text,{size=9.5,color=ink,font=regular,gap=8}={}){const lines=wrap(text,C,size,font),leading=size*1.45;for(const line of lines){ensure(leading);page.drawText(line,{x:M,y,font,size,color});y-=leading}y-=gap}
function heading(text,level=2){const size=level===1?22:level===2?15:11;ensure(size*3);para(text,{size,font:bold,color:ink,gap:10})}
function linkedSource(label,rawUrl){const url=safeSourceUrl(rawUrl);if(!url){para(label+' (link unavailable)',{size:8.5,color:muted});return}const lines=wrap(label,C,8.5);ensure(lines.length*12+22);const top=y;for(const line of lines){page.drawText(line,{x:M,y,font:regular,size:8.5,color:blue});y-=12}const annotation=doc.context.register(doc.context.obj({Type:'Annot',Subtype:'Link',Rect:[M,y,W-M,top+10],Border:[0,0,0],A:{Type:'Action',S:'URI',URI:PDFString.of(url)}}));const annots=page.node.lookup(PDFName.of('Annots'));if(annots)annots.push(annotation);else page.node.set(PDFName.of('Annots'),doc.context.obj([annotation]));para(url,{size:6.7,color:muted,gap:7})}
function table(headers,rows,widths){const scale=C/widths.reduce((a,b)=>a+b,0),ws=widths.map(v=>v*scale);const row=(cells,isHeader=false)=>{const wrapped=cells.map((c,i)=>wrap(c,ws[i]-10,8,isHeader?bold:regular)),rh=Math.max(...wrapped.map(a=>a.length))*11+14;ensure(rh);if(isHeader)page.drawRectangle({x:M,y:y-rh+8,width:C,height:rh,color:rgb(.91,.94,.97)});let x=M;wrapped.forEach((ls,i)=>{ls.forEach((line,j)=>page.drawText(line,{x:x+5,y:y-j*11-3,font:isHeader?bold:regular,size:8,color:ink}));x+=ws[i]});y-=rh;page.drawLine({start:{x:M,y:y+8},end:{x:W-M,y:y+8},color:rgb(.83,.87,.9),thickness:.4})};row(headers,true);if(!rows.length)para('No rows match the current filters.',{size:9,color:muted});for(const cells of rows){if(y-70<54){newPage();row(headers,true)}row(cells)}y-=12}
function diagram(d){const height=230;ensure(height+25);const ids=[...new Set(d.edges.flatMap(e=>[e.from,e.to]))],nodes={};ids.forEach((id,i)=>{const a=-Math.PI/2+i*2*Math.PI/ids.length;nodes[id]=[M+C/2+190*Math.cos(a),y-height/2+90*Math.sin(a)]});for(const [i,e]of d.edges.entries()){const a=nodes[e.from],b=nodes[e.to],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy),ux=dx/len,uy=dy/len,trim=1/Math.max(Math.abs(ux)/47,Math.abs(uy)/18),end={x:b[0]-ux*trim,y:b[1]-uy*trim};const pair=d.edges.filter(v=>[v.from,v.to].sort().join('|')===[e.from,e.to].sort().join('|')),pi=pair.findIndex(v=>v===e),bend=(pi-(pair.length-1)/2)*27*(ids.indexOf(e.from)<ids.indexOf(e.to)?1:-1),mid={x:(a[0]+b[0])/2-uy*bend,y:(a[1]+b[1])/2+ux*bend};page.drawLine({start:{x:a[0]+ux*trim,y:a[1]+uy*trim},end:mid,thickness:1,color:blue});page.drawLine({start:mid,end,thickness:1,color:blue});page.drawLine({start:end,end:{x:end.x-ux*7-uy*3,y:end.y-uy*7+ux*3},thickness:1,color:blue});page.drawLine({start:end,end:{x:end.x-ux*7+uy*3,y:end.y-uy*7-ux*3},thickness:1,color:blue});page.drawText(String(i+1),{x:mid.x+3,y:mid.y+3,font:bold,size:8,color:green})}ids.forEach(id=>{const [x,yy]=nodes[id],name=d.names[id]||id;page.drawRectangle({x:x-47,y:yy-17,width:94,height:34,color:ink});const lines=wrap(name,88,8,bold).slice(0,2);lines.forEach((line,i)=>page.drawText(line,{x:x-bold.widthOfTextAtSize(line,8)/2,y:yy+(lines.length===1?-3:4)-i*10,font:bold,size:8,color:rgb(1,1,1)}))});y-=height+10;para('Direction of funding, commercial spend or non-cash value. Equal-width arrows; amounts and status are listed below.',{size:7.5,color:muted})}
newPage();heading(model.title,1);para(model.subtitle,{size:10,color:muted});para('Saved research snapshot, not live market data. Company-wide accounts and mixed reporting periods. Conditional analysis is not a forecast of stock returns.',{size:8.5,color:muted});for(const section of model.sections){topic=section.heading||topic;if(section.diagram){const intro=(section.paragraphs||[]).reduce((h,p)=>h+wrap(p,C,9.5).length*13.775+8,0);ensure(Math.min(640,330+intro))}if(section.pageBreak&&y<H-100)newPage();if(section.heading)heading(section.heading,section.level||2);for(const p of section.paragraphs||[])para(p);if(section.diagram)diagram(section.diagram);if(section.table)table(section.table.headers,section.table.rows,section.table.widths);for(const source of section.sources||[])linkedSource(source.title||source.label||'Source',source.url)}const pages=doc.getPages();pages.forEach((p,i)=>{p.drawLine({start:{x:M,y:42},end:{x:W-M,y:42},color:rgb(.83,.87,.9),thickness:.5});p.drawText('AI Money Map  |  Dated evidence; see source definitions',{x:M,y:28,font:regular,size:7,color:muted});p.drawText(`${i+1} / ${pages.length}`,{x:W-M-42,y:28,font:regular,size:7,color:muted})});return await doc.save()}
function reportCurrency(n,cur='USD'){if(!Number.isFinite(n))return 'Unavailable';if(n===0)return cur+' 0';const a=Math.abs(n),scale=a>=1e12?1e12:a>=1e9?1e9:a>=1e6?1e6:a>=1e3?1e3:1,suffix=a>=1e12?'T':a>=1e9?'B':a>=1e6?'M':a>=1e3?'K':'';return cur+' '+(n/scale).toFixed(2)+suffix}
function makeReportModel(kind,ticker){const titles={circulation:'How AI money circulates',valuation:'Valuation and debt comparison',scenario:currentScenario().name+' - through 2030',full:'AI Money Map - complete research edition',company:(companies.find(c=>c.ticker===ticker)?.name||ticker)+' - company research'};const model={title:titles[kind],subtitle:'Evidence as of 3 October 2026 | Stock prices: 2 October 2026',sections:[]},sections=model.sections;
function addCirculation(full){const cases=full?circulationData.cases:circulationCases(),edges=full?circulationData.edges:flowFiltered();sections.push({heading:'Reading the circulation map',paragraphs:[`Scope: ${full?'all tiers and relationships':circulationTier==='all'?'all tiers; current ledger filters':'tier '+circulationTier+'; current ledger filters'}. ${cases.length} case studies and ${edges.length} ledger links.`,...circulationData.methodology,'No total circular-dollar figure is calculated. Investments, guarantees, facilities, purchase commitments, receivables and recognized revenues are different, overlapping measures. Closed relationship paths do not prove the same cash recycled.']});for(const c of cases){const ce=c.edgeIds.map(id=>circulationData.edges.find(e=>e.id===id)).filter(Boolean);sections.push({heading:`Tier ${c.tier}: ${c.title}`,paragraphs:[c.summary,'Classification: '+c.kind],diagram:{edges:ce,names:Object.fromEntries(circulationData.nodes.map(n=>[n.id,n.name]))}});ce.forEach((e,i)=>sections.push({heading:`${i+1}. ${nodeName(e.from)} -> ${nodeName(e.to)}`,level:3,paragraphs:[`${e.title}. ${e.amountLabel}. Status: ${e.status}.`,e.detail],sources:e.sourceIds.map(id=>circulationData.sources[id]).filter(Boolean)}));sections.push({heading:'Interpretation and boundary',level:3,paragraphs:[c.insight,c.limitation]})}sections.push({heading:'Filtered relationship ledger',pageBreak:true,table:{headers:['From -> To','Relationship / status','Amount / scope'],widths:[140,205,162],rows:edges.map(e=>[nodeName(e.from)+' -> '+nodeName(e.to),e.title+' / '+e.status,e.amountLabel])}})}
function addValuation(full){const list=full?companies:valuationFiltered();sections.push({heading:'Valuation and financing',pageBreak:true,paragraphs:[`Scope: ${list.length} companies. ${full?'Complete universe.':'Current valuation filters apply.'}`,...valuationData.methodology],table:{headers:['Company','Equity value','P/E','FCF yield','Gross debt / cash','Net debt'],widths:[100,89,46,52,128,92],rows:list.map(c=>{const v=valuationRecord(c);return [c.name+' / '+c.ticker,reportCurrency(v.marketCap,v.marketCurrency||c.market.currency),ratio(v.pe),ratio(v.fcfYield,'%'),reportCurrency(v.grossDebt,v.currency)+' / '+reportCurrency(v.cash,v.currency),reportCurrency(v.netDebt,v.currency)]})}});list.forEach(c=>{const v=valuationRecord(c);sections.push({heading:c.name+' ('+c.ticker+')',level:3,paragraphs:[`Debt: ${v.debtDate||'unavailable'}; cash: ${v.cashDate||'unavailable'}; shares: ${v.shareDate||'unavailable'}; ${valuationPeriodText(v)} ${v.debtDefinition||'Debt definition unavailable.'}`,`Liquid funds including short-term investments: ${reportCurrency(v.liquidFunds,v.currency)}. Separately captured finance leases: ${reportCurrency(v.financeLeases,v.currency)}. Net debt/FCF: ${ratio(v.netDebtToFcf)}. ${debtBasisText(v)}. Borrowings including separately captured finance leases: ${reportCurrency(v.totalDebtIncludingFinanceLeases,v.currency)}; lease-adjusted cash-only net debt: ${reportCurrency(v.leaseAdjustedNetDebt,v.currency)}.`,...(v.notes||[]),...(v.missingReasons||[])],sources:v.sources||[]})})}
function addScenario(i){const s=scenariosData.scenarios[i],list=companies.filter(c=>hiddenInScenario(c,i));sections.push({heading:'2030: '+s.name,pageBreak:true,paragraphs:[s.summary,...s.assumptions.map(([k,v])=>k+': '+v),s.risk,'Spending paths and ratings are authored assumptions, not assigned probabilities or target share prices.']});for(const [label,cs]of [['Conditional business winners',s.winners.map(t=>companies.find(c=>c.ticker===t))],['Hidden-champion candidates',list],['Vulnerable companies and weaker fits',s.losers.map(t=>companies.find(c=>c.ticker===t))]]){sections.push({heading:label,paragraphs:label==='Hidden-champion candidates'?[`Recognition setting: ${recognitionWindow==='both'?'both since-2023 and one-year underperformance':'one-year lag only'}; required one-year lag: ${recognitionGap} percentage points. ${cs.length} pass. This does not establish fair value.`]:[]});cs.forEach(c=>sections.push({heading:c.name+' ('+c.ticker+')',level:3,paragraphs:[scenarioNote(c,i),'Counterargument: '+scenariosData.profiles[c.ticker].risk,'Next evidence: '+scenariosData.profiles[c.ticker].watch,scenarioMarketText(c)],sources:scenariosData.profiles[c.ticker].sources.map(id=>scenariosData.sources[id])}))}sections.push({heading:'Signposts',paragraphs:[...s.watch,'What would change the conclusion: '+s.invalidate]})}
function addCompany(c){const v=valuationRecord(c);sections.push({heading:'Business and reported financials',paragraphs:[c.role,`${c.basis}: ${c.start} to ${c.end}. Reporting currency ${c.currency}. ${c.stale?'Older reporting period.':''}`,c.dataNote||''],table:{headers:['Measure','Reported amount'],widths:[270,237],rows:[['Revenue',reportCurrency(val(c,'revenue'),c.currency)],['Net income',reportCurrency(val(c,'net'),c.currency)],['Operating cash flow',reportCurrency(val(c,'ocf'),c.currency)],['Cash capital expenditure',reportCurrency(val(c,'capex'),c.currency)],['Free cash flow',reportCurrency(val(c,'fcf'),c.currency)],['Equity value',reportCurrency(v.marketCap,v.marketCurrency||c.market.currency)],['P/E',ratio(v.pe)],['FCF yield',ratio(v.fcfYield,'%')],['Gross debt',reportCurrency(v.grossDebt,v.currency)],['Cash',reportCurrency(v.cash,v.currency)],['Net debt',reportCurrency(v.netDebt,v.currency)]]}});sections.push({heading:'Definitions and financing limitations',paragraphs:[c.fcfDefinition||'FCF definition unavailable',v.debtDefinition||'Debt unavailable',`Debt date ${v.debtDate||'unavailable'}. Cash date ${v.cashDate||'unavailable'}. ${valuationPeriodText(v)} Share date ${v.shareDate||'unavailable'}. Finance leases separately captured: ${reportCurrency(v.financeLeases,v.currency)}.`,...(v.notes||[]),...(v.missingReasons||[])]});sections.push({heading:'Stock recognition',paragraphs:[scenarioMarketText(c),c.market.definition,'Benchmark underperformance is not a fair-value estimate.']});scenariosData.scenarios.forEach((s,i)=>sections.push({heading:s.name,paragraphs:[`Relative business position: ${scenarioRating(c,i)} / ${ratingLabel(scenarioRating(c,i))}.`,scenarioNote(c,i)]}));sections.push({heading:'Counterargument and evidence',paragraphs:[scenariosData.profiles[c.ticker].risk,scenariosData.profiles[c.ticker].watch],sources:[...c.sources,...v.sources,...scenariosData.profiles[c.ticker].sources.map(id=>scenariosData.sources[id])]})}
if(kind==='circulation'||kind==='full')addCirculation(kind==='full');if(kind==='scenario')addScenario(scenarioIndex);if(kind==='full')for(let i=0;i<3;i++)addScenario(i);if(kind==='valuation'||kind==='full')addValuation(kind==='full');if(kind==='company')addCompany(companies.find(c=>c.ticker===ticker));return model}
const reportUrls=new Map();
async function downloadResearchReport(kind,ticker){
 const status=kind==='company'?$('#company-pdf-status'):$('#pdf-status');status.hidden=false;status.textContent='Creating your PDF…';
 try{const model=makeReportModel(kind,ticker),bytes=await buildResearchPdf(model),blob=new Blob([bytes],{type:'application/pdf'});if(reportUrls.has(status.id))URL.revokeObjectURL(reportUrls.get(status.id));const url=URL.createObjectURL(blob);reportUrls.set(status.id,url);status.textContent=`PDF ready · ${Math.ceil(bytes.length/1024)} KB · `;const a=document.createElement('a');a.href=url;a.download=`ai-money-map-${ticker||kind}-2026-10-03.pdf`;a.textContent='Download PDF';status.appendChild(a);const close=document.createElement('button');close.textContent='Dismiss';close.onclick=()=>status.hidden=true;status.appendChild(close)}catch(e){console.error(e);status.textContent='The PDF could not be created. Please reload and try again.'}
}
